    private const STARTER_LOGISTICS_BODY_EN = '<h2>Every shipment has operational and financial events</h2><p>A transport or logistics platform can connect booking, sender and receiver details, route stages, cargo documents, charges, agent activity, delivery status and customer accounts.</p><h2>Define the tracking model</h2><ul><li>Shipment number, origin, destination and responsible parties</li><li>Packages, weight, volume and approved charge rules</li><li>Route milestones, handovers and status history</li><li>Expenses, advances, collections and agent settlements</li><li>Customer notifications and document access where approved</li></ul><p>The correct design depends on whether the company handles cargo, fleet operations, freight forwarding, warehousing or a combination of services.</p>';

    public function run(): void
    {
        ContentPage::query()->firstOrCreate(['slug' => 'financial-management-software-afghanistan'], $this->finance());

        $logistics = ContentPage::query()->where('slug', 'transport-logistics-software-afghanistan')->first();

        if (! $logistics) {
            ContentPage::query()->create(array_merge($this->logistics(), [
                'type' => 'industry', 'slug' => 'transport-logistics-software-afghanistan',
                'status' => 'published', 'featured' => true, 'sort_order' => 8, 'published_at' => now(),
            ]));

            return;
        }

        // Upgrade only the known starter copy. CMS-managed editorial changes always win.
        if ($logistics->translation('body', 'en') === self::STARTER_LOGISTICS_BODY_EN) {
            $logistics->update($this->logistics());
        }
    }

