    private function logisticsFaqs(): array
    {
        return [
            $this->faq('What logistics operations can the platform support?', 'The approved scope may cover cargo bookings, freight forwarding, fleet dispatch, carrier management, warehousing, delivery, billing and settlement individually or in a connected model.', 'پلتفرم کدام عملیات لوژستیک را پشتیبانی می‌کند؟', 'محدوده می‌تواند ثبت بار، freight forwarding، دیسپچ وسایط، حامل، گدام، تحویل، بل و تصفیه را جدا یا یکپارچه پوشش دهد.', 'پلېټفارم کوم لوژستیک عملیات اداره کوي؟', 'تایید شوي حدود د بار ثبت، freight forwarding، fleet دیسپچ، وړونکي، ګدام، تحویل، بل او تصفیه جلا یا تړلي پوښلی شي.'),
            $this->faq('Can customers track shipments?', 'A customer portal or approved notifications can show permitted milestones, documents and delivery evidence without exposing internal or other-customer information.', 'آیا مشتری محموله را پیگیری می‌کند؟', 'پورتال یا اطلاع تأییدشده می‌تواند مراحل، اسناد و شواهد مجاز را بدون افشای معلومات داخلی یا مشتری دیگر نشان دهد.', 'ایا مشتری خپل بار تعقیبولی شي؟', 'پورټل یا تایید شوې خبرتیا مجاز پړاوونه، اسناد او شواهد ښيي، خو داخلي یا د بل مشتری معلومات نه افشا کوي.'),
            $this->faq('Can it manage owned vehicles and external carriers?', 'Yes, but they use different workflows. Owned fleet may require drivers, fuel and maintenance; external carriers may require rates, tendering, documents, freight bills and settlement.', 'آیا وسایط خودی و حامل بیرونی را مدیریت می‌کند؟', 'بلی، اما روند جدا دارد. وسایط خودی به راننده، تیل و نگهداری و حامل بیرونی به نرخ، tender، اسناد، بل فریت و تصفیه نیاز دارد.', 'ایا خپل وسایط او بهرني وړونکي اداره کوي؟', 'هو، خو جلا بهیرونه لري. خپل fleet ډرېور، تېل او ساتنه غواړي؛ بهرنی وړونکی نرخ، tender، اسناد، freight bill او تصفیه غواړي.'),
            $this->faq('Can GPS or mobile applications be integrated?', 'Integration can be evaluated after the provider, device, connectivity, data ownership, API, permissions, failure handling and reconciliation requirements are verified.', 'آیا GPS یا اپ موبایل ادغام می‌شود؟', 'پس از تأیید ارائه‌کننده، دستگاه، اتصال، مالکیت معلومات، API، صلاحیت، مدیریت خطا و مطابقت، ادغام ارزیابی می‌شود.', 'ایا GPS یا موبایل اپ ادغامېږي؟', 'د چمتو کوونکي، وسیلې، انټرنېټ، د معلوماتو مالکیت، API، صلاحیت، خطا او مطابقت له تایید وروسته ادغام ارزول کېږي.'),
            $this->faq('Can existing customers, fleet and open shipments be migrated?', 'Approved customers, routes, vehicles, partners, rates, open shipments, balances and documents can be migrated after mapping, cleaning and validation.', 'آیا مشتری، وسایط و محموله باز انتقال می‌شود؟', 'مشتری، مسیر، وسیله، شریک، نرخ، محموله باز، بیلانس و سند تأییدشده پس از نقشه، پاک‌سازی و اعتبارسنجی منتقل می‌شود.', 'ایا مشتریان، وسایط او پرانیستي بارونه لېږدول کېږي؟', 'تایید شوي مشتریان، لارې، وسایط، شریکان، نرخونه، پرانیستي بارونه، بیلانسونه او اسناد له نقشې، پاکولو او تایید وروسته لېږدول کېږي.'),
            $this->faq('How is logistics software priced?', 'Fida prepares a scope-based quotation after reviewing services, locations, shipment volumes, fleet or carriers, warehouses, integrations, migration, users, deployment and support.', 'قیمت نرم‌افزار لوژستیک چگونه تعیین می‌شود؟', 'فدا پس از بررسی خدمت، موقعیت، حجم محموله، وسایط یا حامل، گدام، ادغام، انتقال، کاربر، نصب و پشتیبانی پیشنهاد می‌دهد.', 'د لوژستیک سافټویر بیه څنګه ټاکل کېږي؟', 'فدا د خدمتونو، ځایونو، د بار حجم، fleet یا وړونکو، ګدامونو، ادغام، لېږد، کاروونکو، نصب او ملاتړ له کتنې وروسته نرخ ورکوي.'),
        ];
    }

    private function faq(string $enQuestion, string $enAnswer, string $faQuestion, string $faAnswer, string $psQuestion, string $psAnswer): array
    {
        return ['question' => ['en' => $enQuestion, 'fa' => $faQuestion, 'ps' => $psQuestion], 'answer' => ['en' => $enAnswer, 'fa' => $faAnswer, 'ps' => $psAnswer]];
    }
}
